package org.rabochaya.maptests;
import android.app.*;import android.content.*;import android.net.Uri;import android.widget.TextView;import java.io.*;import java.lang.reflect.*;import java.util.*;import org.json.*;
/** DEM vertical slice in the existing layer/reopen process lifecycle, no new mode. */
final class DemChecks {
 final MapAndroidChecks m;final MapLayersChecks layers;final ManagerRotationChecks r;final ManagerVisualChecks v;DemChecks(MapAndroidChecks m){this.m=m;layers=new MapLayersChecks(m);r=new ManagerRotationChecks(m);v=new ManagerVisualChecks(m);}
 File target(long id)throws Exception{return (File)m.staticCall("DemActivity","file",new Class[]{Context.class,long.class},m.getTargetContext(),id);}
 JSONObject payloads(Object doc)throws Exception{JSONObject result=new JSONObject();for(Map.Entry<String,byte[]> e:m.assets(doc).entrySet())result.put(e.getKey(),android.util.Base64.encodeToString(e.getValue(),android.util.Base64.NO_WRAP));return result;}
 void open(long id)throws Exception{v.finish();m.activity=m.startActivitySync(new Intent().setClassName(m.getTargetContext().getPackageName(),"org.rabochaya.projects.DemActivity").putExtra("project",id).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));m.waitText("Открыть локальный HGT");}
 void select(File file)throws Exception{final Throwable[] error={null};m.runOnMainSync(()->{try{Method result=m.activity.getClass().getDeclaredMethod("onActivityResult",int.class,int.class,Intent.class);result.setAccessible(true);result.invoke(m.activity,4601,Activity.RESULT_OK,new Intent().setData(Uri.fromFile(file)));}catch(Throwable e){error[0]=e;}});if(error[0]!=null)throw new AssertionError(error[0]);m.waitText("Готов к установке");}
 void source(File file)throws Exception{try(BufferedOutputStream out=new BufferedOutputStream(new FileOutputStream(file))){for(int y=0;y<=1200;y++){byte[] row=new byte[2402];for(int x=0;x<=1200;x++){int h=x==500&&y==500?Short.MIN_VALUE:2*x+y-1800;row[x*2]=(byte)(h>>8);row[x*2+1]=(byte)h;}out.write(row);}}}
 void phase(String step){android.util.Log.i("RK_DEM",step);android.os.Bundle status=new android.os.Bundle();status.putString("stream","DEM_PHASE "+step+"\n");m.sendStatus(0,status);}
 void main(long id)throws Exception{v.finish();phase("before-fresh-main-launch owner="+id);m.activity=m.startActivitySync(new Intent().setClassName(m.getTargetContext().getPackageName(),"org.rabochaya.projects.LocalMapActivity").putExtra("project",id).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_MULTIPLE_TASK));m.waitText("видимых объектов");m.check((Long)m.editorField("projectId")==id&&m.activity.getIntent().getLongExtra("project",-1)==id,"fresh map Activity belongs to the exact DEM project, never reused layer task");phase("fresh-main-created owner="+id+" task="+m.activity.getTaskId());m.setViewport((5.5+180)/360,(1-Math.log(Math.tan(Math.PI/4+Math.toRadians(10.5)/2))/Math.PI)/2,10);m.waitText("DEM: 0.0 м");phase("manual-centre-height-zero");m.runOnMainSync(()->{try{TextView panel=(TextView)m.editorField("coordinates");m.check(panel.isShown()&&v.fullyVisible(panel),"manual centre height and coordinates are physically visible");m.check(panel.getTypeface()==m.staticCall("WorkspaceUi","font",new Class[]{Activity.class},m.activity),"DEM centre uses owned Arimo");}catch(Exception e){throw new RuntimeException(e);}});}
 void prepare()throws Exception{Context c=m.getTargetContext();Object store=m.storeClass.getConstructor(Context.class).newInstance(c);long id=-1;File raw=null;boolean keep=false;int requests=m.requests.get();try{id=new GeometryConfirmationChecks(m).fixture(store,false);Object doc=r.load(store,id);byte[] xml=r.xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));File dir=new File(c.getCacheDir(),"qa-dem-"+id);m.check(dir.mkdir(),"own synthetic HGT directory fresh");raw=new File(dir,"N10E005.hgt");source(raw);byte[] input=m.hash(raw);open(id);select(raw);m.check(!target(id).exists(),"HGT selection only prepares private input, no installation");m.capture("mvisual-dem-import-ready");m.click("К карте");m.check(!target(id).exists(),"Cancel/back after HGT selection leaves project DEM absent");layers.unchanged(store,id,xml,assets);
  open(id);select(raw);m.click("Установить DEM");m.waitText("Установлен DEM");File owned=target(id);m.check(owned.isFile()&&Arrays.equals(input,m.hash(raw)),"explicit DEM install retains exact source HGT");Object reader=m.staticCall("HgtRaster","owned",new Class[]{File.class,long.class},owned,id);try{m.check((Double)m.call(reader,"height",new Class[]{double.class,double.class},5.5,10.5)==0,"installed DEM bilinear centre height is independent known zero");}finally{m.call(reader,"close",new Class[]{});}byte[] installed=m.hash(owned);m.click("Убрать DEM");m.click("Отмена");m.check(Arrays.equals(installed,m.hash(owned)),"Cancel DEM removal preserves exact container");
  long other=c.getSharedPreferences("qa_layers",0).getLong("other",-1);m.check(other>0,"unrelated project exists");Object otherDoc=r.load(store,other);byte[] otherXml=r.xml(otherDoc);Map<String,byte[]> otherAssets=new HashMap<>(m.assets(otherDoc));File prepared=File.createTempFile("qa-foreign-dem-",".tmp",c.getFilesDir());try{m.staticCall("HgtRaster","prepare",new Class[]{File.class,String.class,File.class,long.class},raw,"N10E005.hgt",prepared,other);String before=(String)m.staticCall("LocalRasterStore","stamp",new Class[]{File.class},owned);m.staticCall("LocalRasterStore","replace",new Class[]{File.class,File.class,String.class},prepared,owned,before);byte[] foreign=m.hash(owned);m.click("Убрать DEM");m.click("Убрать");m.waitText("DEM не изменён");m.check(Arrays.equals(foreign,m.hash(owned)),"old remove screen cannot delete a foreign replacement DEM");m.check(!(Boolean)m.staticCall("DemActivity","cleanup",new Class[]{Context.class,long.class},c,id)&&Arrays.equals(foreign,m.hash(owned)),"automatic cleanup refuses foreign owner header");v.finish();open(id);m.check(!v.button(m.activity.getWindow().getDecorView(),"Открыть локальный HGT").isEnabled(),"foreign owner on open disables replacement input");m.staticCall("HgtRaster","prepare",new Class[]{File.class,String.class,File.class,long.class},raw,"N10E005.hgt",prepared,id);String current=(String)m.staticCall("LocalRasterStore","stamp",new Class[]{File.class},owned);m.staticCall("LocalRasterStore","replace",new Class[]{File.class,File.class,String.class},prepared,owned,current);}finally{prepared.delete();}
  main(id);m.capture("dem-manual-centre");m.setViewport(.5,.5,2);m.waitText("DEM: нет данных");m.check(Arrays.equals(installed,m.hash(owned)),"panning/outside coverage does not rewrite DEM");layers.unchanged(store,id,xml,assets);layers.unchanged(store,other,otherXml,otherAssets);m.check(m.requests.get()==requests,"HGT import/height/pan/refusals issue zero requests");c.getSharedPreferences("qa_dem",0).edit().putLong("project",id).putString("xml",android.util.Base64.encodeToString(xml,android.util.Base64.NO_WRAP)).putString("assets",payloads(r.load(store,id)).toString()).putString("hash",android.util.Base64.encodeToString(installed,android.util.Base64.NO_WRAP)).putString("source",raw.getPath()).putString("source_hash",android.util.Base64.encodeToString(input,android.util.Base64.NO_WRAP)).commit();keep=true;
 }finally{v.finish();if(!keep&&id>0){m.call(store,"remove",new Class[]{long.class},id);m.staticCall("LocalMapActivity","cleanupDeletedProject",new Class[]{Context.class,long.class},c,id);if(raw!=null){raw.delete();raw.getParentFile().delete();}}m.call(store,"close",new Class[]{});}}
 void reopen()throws Exception{phase("reopen-enter");int requests=m.requests.get();Context c=m.getTargetContext();android.content.SharedPreferences p=c.getSharedPreferences("qa_dem",0);long id=p.getLong("project",-1);Object store=m.storeClass.getConstructor(Context.class).newInstance(c);try{m.check(id>0,"DEM fixture retained through actual force-stop");m.check(Arrays.equals(m.hash(target(id)),android.util.Base64.decode(p.getString("hash",""),android.util.Base64.NO_WRAP)),"same owned DEM bytes survive restart");File raw=new File(p.getString("source",""));m.check(Arrays.equals(m.hash(raw),android.util.Base64.decode(p.getString("source_hash",""),android.util.Base64.NO_WRAP)),"restart leaves source HGT exact");phase("reopen-owned-and-source-hashes-exact");main(id);m.capture("mvisual-dem-restarted");phase("reopen-height-png-saved");new MapLayersChecks(m).unchanged(store,id,android.util.Base64.decode(p.getString("xml",""),android.util.Base64.NO_WRAP),new CompositionDownloadChecks(m).payloads(new JSONObject(p.getString("assets","{}"))));phase("before-owned-remove-screen");open(id);m.click("Убрать DEM");m.click("Убрать");m.waitText("DEM убран");phase("owned-remove-complete");m.check(!target(id).exists()&&raw.isFile(),"explicit DEM removal keeps original HGT");m.check(m.requests.get()==requests,"DEM restart and removal add no network requests");raw.delete();raw.getParentFile().delete();}finally{v.finish();if(id>0){m.call(store,"remove",new Class[]{long.class},id);m.staticCall("LocalMapActivity","cleanupDeletedProject",new Class[]{Context.class,long.class},c,id);}m.call(store,"close",new Class[]{});}}
}
